627	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
628	    @Override
629	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
630	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
631	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
632	        rejectCityAtCapacity(ownerFieldsDto.getCity());
633	        HttpHeaders headers = new HttpHeaders();
634	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
635	        owner.setAddress(normalizedAddress);
636	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
637	        owner.setTelephone(normalizedTelephone);
638	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
639	        owner.setEmail(normalizedEmail);
640	        validatePostcode(owner.getCity(), owner.getPostcode());
641	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
642	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
643	        rejectFutureRegistrationDate(owner.getRegistrationDate());
644	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
645	        LocalDate registrationDate = toBusinessDay(effectiveDate);
646	        rejectDailyOwnerLimit(registrationDate);
647	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
648	        owner.setRegistrationDate(registrationDate);
649	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
650	        owner.setCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName()));
651	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
652	        owner.setHouseholdId(householdId);
653	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
654	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
655	        owner.setMembershipLevel(membershipLevelFor(owner));
656	        this.clinicService.saveOwner(owner);
657	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
658	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
659	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
660	        headers.setLocation(UriComponentsBuilder.newInstance()
661	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
662	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
663	    }
664	
665	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
666	    @Override
667	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
668	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
669	        if (currentOwner == null) {
670	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
671	        }
672	        currentOwner.setAddress(ownerFieldsDto.getAddress());
673	        currentOwner.setCity(ownerFieldsDto.getCity());
674	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
675	        currentOwner.setLastName(ownerFieldsDto.getLastName());
676	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
677	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
678	        this.clinicService.saveOwner(currentOwner);
679	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
680	    }
681	
682	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
683	    @Transactional
684	    @Override
685	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
686	        Owner owner = this.clinicService.findOwnerById(ownerId);
687	        if (owner == null) {
688	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	        }
690	        this.clinicService.deleteOwner(owner);
691	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
697	        Owner owner = this.clinicService.findOwnerById(ownerId);
698	        if (owner == null) {
699	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	        }
701	        HttpHeaders headers = new HttpHeaders();
702	        Pet pet = petMapper.toPet(petFieldsDto);
703	        owner.setId(ownerId);
704	        pet.setOwner(owner);
705	        pet.getType().setName(null);
706	        this.clinicService.savePet(pet);
707	        PetDto petDto = petMapper.toPetDto(pet);
708	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
709	            .buildAndExpand(pet.getId()).toUri());
710	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
716	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
717	        if (currentOwner != null) {
718	            Pet currentPet = this.clinicService.findPetById(petId);
719	            if (currentPet != null) {
720	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
721	                currentPet.setName(petFieldsDto.getName());
722	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
723	                this.clinicService.savePet(currentPet);
724	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
725	            }
726	        }
727	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
728	    }
729	
